@Test
void 동시성() throws Exception {
    ExecutorService pool = Executors.newFixedThreadPool(2);
    List<Future<String>> futures = new ArrayList<>();

    for (String name : List.of("m1", "m2")) {
        futures.add(pool.submit(() -> txTemplate.execute(status -> {
            Member found = queryFactory.selectFrom(member)
                    .where(member.username.eq(name))
                    .fetchOne();
            return Thread.currentThread().getName()
                    + " -> " + found.getUsername()
                    + " (em " + System.identityHashCode(
                        ((EntityManagerProxy) em).getTargetEntityManager())
                    + ")";
        })));
    }

    for (Future<String> f : futures) System.out.println(f.get());
    pool.shutdown();
}

