@Test
@Transactional
void 세_방법() {
    em.clear();
    System.out.println("--- 매번 new ---");
    new JPAQueryFactory(em).selectFrom(member)
            .where(member.age.goe(30)).fetch();

    em.clear();
    System.out.println("--- 필드 ---");
    JPAQueryFactory local = new JPAQueryFactory(em);
    local.selectFrom(member).where(member.age.goe(30)).fetch();

    em.clear();
    System.out.println("--- 빈 ---");
    queryFactory.selectFrom(member).where(member.age.goe(30)).fetch();
}

